import { betterAuth } from 'better-auth';
import { prismaAdapter } from 'better-auth/adapters/prisma';
import prisma from './db';

/**
 * Better Auth instance.
 * Handles signup, login, logout, and session management.
 * The prismaAdapter reads/writes the users, sessions, accounts,
 * and verifications tables generated by the Prisma schema.
 */
export const auth = betterAuth({
  database: prismaAdapter(prisma, { provider: 'postgresql' }),

  baseURL: process.env.BETTER_AUTH_URL ?? 'http://localhost:3000',
  secret: process.env.BETTER_AUTH_SECRET ?? 'dev_secret_change_in_prod',

  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false,
  },

  session: {
    expiresIn: 60 * 60 * 8,       // 8 hours
    updateAge:  60 * 60,           // refresh every hour
    cookieCache: { enabled: true, maxAge: 60 * 5 },
  },

  user: {
    additionalFields: {
      role: {
        type: 'string',
        defaultValue: 'USER',
        input: false,              // not settable by the client on sign-up
      },
    },
  },
});
